/**
 * Builder work order §6: re-derives every manifest's refrain splits fresh from the SAME rule
 * scripts/tag-refrain-splits.ts uses, and fails if what's actually stored on disk (the
 * `refrainSplit` field on each GUIDE line) doesn't match exactly — in either direction: a fragment
 * that doesn't complete the full GUIDE -> PAUSE -> PONTA pattern must carry no `refrainSplit` at
 * all, and a line marked `refrainSplit` must genuinely satisfy the pattern. The field is always
 * regenerated by `tag-refrain-splits.ts`, never hand-edited — this is the guard that catches it
 * drifting out of sync (a manifest edited after tagging, a hand-added field, etc.).
 *
 * Usage: npx tsx scripts/lint-refrain-splits.ts
 */
import { readdirSync, readFileSync } from 'node:fs';
import { resolve, join } from 'node:path';
import { applyRefrainRules, REFRAIN_RULES, type AudioScript } from './tag-refrain-splits.js';

const AUDIO_DIR = resolve(process.cwd(), 'src/audio/content');

function main() {
  const files = readdirSync(AUDIO_DIR).filter((f) => f.endsWith('.json'));
  const problems: string[] = [];

  for (const file of files) {
    const script = JSON.parse(readFileSync(join(AUDIO_DIR, file), 'utf8')) as AudioScript;
    const lines = script.lines ?? [];
    const storedBefore = lines.map((l) => (l.refrainSplit ? { ...l.refrainSplit } : undefined));

    // Re-derive fresh (applyRefrainRules mutates a clone's own lines in place).
    const clone = JSON.parse(JSON.stringify(script)) as AudioScript;
    applyRefrainRules(clone);
    const derived = (clone.lines ?? []).map((l) => l.refrainSplit);

    for (let i = 0; i < lines.length; i++) {
      const before = storedBefore[i];
      const after = derived[i];
      if (JSON.stringify(before) !== JSON.stringify(after)) {
        problems.push(
          `${file} line ${i}: stored refrainSplit ${JSON.stringify(before) ?? 'undefined'} does not match ` +
            `the rule's own derivation ${JSON.stringify(after) ?? 'undefined'} — run ` +
            `\`npx tsx scripts/tag-refrain-splits.ts\` to regenerate.`,
        );
      }
    }

    // A fragment present without completing the pattern (e.g. a GUIDE line containing a refrain
    // fragment whose very next line ISN'T the matching PONTA completion) is a real content bug,
    // not just a tagging-drift issue — flag it explicitly rather than silently leaving it untagged.
    for (let i = 0; i < lines.length; i++) {
      const line = lines[i]!;
      if (line.speaker !== 'GUIDE') continue;
      const rule = REFRAIN_RULES.find((r) => line.text.includes(r.fragment));
      if (!rule) continue;
      const next = lines[i + 1];
      const pauses = line.pauseAfterMs > 0;
      const nextMatches = next?.speaker === 'PONTA' && next.text.startsWith(rule.completion);
      if (!pauses || !nextMatches) {
        problems.push(
          `${file} line ${i}: contains refrain ${rule.refrain}'s own fragment "${rule.fragment}" but does ` +
            `not complete the GUIDE -> PAUSE -> PONTA pattern (pauseAfterMs=${line.pauseAfterMs}, next=` +
            `${next ? `${next.speaker}: "${next.text.slice(0, 20)}..."` : 'END'}).`,
        );
      }
    }
  }

  if (problems.length > 0) {
    console.error(`lint-refrain-splits: ${problems.length} problem(s):\n`);
    for (const p of problems) console.error(`  ${p}`);
    process.exit(1);
  }
  console.log(`lint-refrain-splits: OK (${files.length} manifest(s) checked)`);
}

main();
